# Referencia: comando embutido no item, com macros Zabbix.
test '{$PFSENSE.ZBX.UPDATE.ENABLED}' = 1 || exit 0; test "$(/usr/bin/id -u)" = 0 || exit 1; PATH=/sbin:/bin:/usr/sbin:/usr/bin:/usr/local/sbin:/usr/local/bin; export PATH; umask 022; mkdir -p /root/scripts || exit 1; p=/root/scripts/pfsense_zbx_update.php; if [ ! -f "$p" ] || [ "$(sha256 -q "$p")" != '{$PFSENSE.ZBX.UPDATER.SHA256}' ]; then t=$(mktemp /root/scripts/.pfzu-bootstrap.XXXXXX) || exit 1; trap 'test ! -f "$t" || unlink "$t"' 0; curl --fail --silent --show-error --location --proto =https --proto-redir =https --connect-timeout 10 --max-time 45 --max-filesize 1048576 --output "$t" '{$PFSENSE.ZBX.UPDATER.URL}' && [ "$(sha256 -q "$t")" = '{$PFSENSE.ZBX.UPDATER.SHA256}' ] && /usr/local/bin/php -l "$t" >/dev/null && chmod 0644 "$t" && mv -f "$t" "$p" || exit 1; fi; /usr/local/bin/php "$p" update '{$PFSENSE.ZBX.SCRIPT.URL}' '{$PFSENSE.ZBX.SCRIPT.SHA256}'
